import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { readCapture } from "./reader.ts";
import { replayCapture } from "./compare.ts";

// Native expectations are immutable saved CSP outputs, not generated by the replay.
for (const fixture of [
  { name: "tablet-live-20261011T164934Z", count: 115, stabilization: 0 },
  {
    name: "tablet-manual-20261011T181326.241155Z-172e5259",
    count: 311,
    stabilization: 20,
  },
]) {
  test(`saved native S${fixture.stabilization} stroke matches through release`, () => {
    const path = new URL(
      `../../evidence/debugger-access/${fixture.name}/tablet.jsonl`,
      import.meta.url,
    );
    const capture = readCapture(readFileSync(path, "utf8"));
    const report = replayCapture(capture);
    assert.equal(report.callCount, fixture.count);
    assert.equal(report.observedCompletion.nativeReleaseReturned, true);
    assert.equal(report.observedCompletion.finalSourceReturned, true);
    assert.equal(report.mismatchCount, 0, JSON.stringify(report.firstDifference));
    assert.equal(report.status, "exact_match");
  });
}
